// F-907: the background loop and its button, as a controller over the video element and the page's view of it, so that it is
// tested in Node against a fake video that accepts and refuses play() the ways WebKit does (tests/landing/loop.test.ts).
//
// What the iPad showed at the live test (FEEDBACK.md): the loop did not start by itself, and the button needed two presses.
// The button's words followed the visitor's wish (`userPaused`), never the video: when anything but the visitor stopped it
// (a refused play(), the system pausing it), the button still offered PAUSE over a still picture, so the first press only
// "paused" a paused video, and the second called play() inside a tap, which WebKit always allows. And a refused play() hid
// the button for good. Here the button shows what a press will do, from the video's own events: the play icon whenever the
// loop is not playing for any reason but the page's own (the hero covered, the page hidden), and a press on it calls play()
// at once, inside the tap.
import { shouldPlay, type PlayState } from './video'

/** One of the loop's files and its type: the browser plays the first it can, so exactly one is fetched. */
export type LoopSource = readonly [src: string, type: string]

/** The loop, WebM first. */
export const LOOP_SOURCES: readonly LoopSource[] = [
  ['landing/loop.webm', 'video/webm'],
  ['landing/loop.mp4', 'video/mp4'],
]

/** What the controller uses of the `<video>` (an HTMLVideoElement is one). */
export interface LoopVideo {
  muted: boolean
  defaultMuted: boolean
  playsInline: boolean
  readonly paused: boolean
  setAttribute(name: string, value: string): void
  load(): void
  play(): Promise<void>
  pause(): void
  addEventListener(type: 'play' | 'playing' | 'pause', listener: () => void): void
}

/** What the controller changes on the page around the video. */
export interface LoopView {
  /** Puts these sources in the video, in order, in place of any it has (none: no source). */
  sources(list: readonly LoopSource[]): void
  /** The button: shown or not, and the icon of what a press does. */
  button(shown: boolean, icon: 'pause' | 'play'): void
}

export interface Loop {
  /** Adds the sources and plays (after the page's load event, when `wantsVideo`). */
  start(): void
  /** Back to the poster: no source, no file, no button (reduced motion turned on). */
  stop(): void
  /** The button was pressed. */
  press(): void
  /** Whether some of the video is not covered by the panels. */
  seen(onScreen: boolean): void
  /** Whether the page is visible. */
  visible(pageVisible: boolean): void
}

const isRefusal = (error: unknown): boolean => error instanceof Error && error.name === 'NotAllowedError'

export function createLoop(video: LoopVideo, view: LoopView, sources: readonly LoopSource[] = LOOP_SOURCES): Loop {
  const state: PlayState = { userPaused: false, pageVisible: true, onScreen: true }
  let started = false
  /** The browser refused play() or stopped the loop on its own: it waits for a press. */
  let stopped = false
  /** The button has been shown: the loop played, or it was refused and waits for a press. */
  let shown = false
  /** A pause the page asked for, whose event has not come yet. */
  let pausing = false

  const draw = (): void => view.button(started && shown, state.userPaused || stopped ? 'play' : 'pause')

  // A refused play() (Low Power Mode, an autoplay policy) leaves the poster and offers the play icon; an aborted one (the
  // page paused or reloaded the video before it started) is the page's own doing, and nothing is reported.
  const update = (): void => {
    if (!started) return
    if (shouldPlay(state)) {
      video.play().catch((error: unknown) => {
        if (!started || !isRefusal(error)) return
        stopped = true
        shown = true
        draw()
      })
    } else if (!video.paused) {
      pausing = true
      video.pause()
    }
  }

  video.addEventListener('play', () => {
    stopped = false
    draw()
  })
  video.addEventListener('playing', () => {
    stopped = false
    shown = true
    draw()
  })
  video.addEventListener('pause', () => {
    if (pausing) pausing = false
    else if (started && !state.userPaused) stopped = true
    draw()
  })

  return {
    start() {
      if (started) return
      started = true
      // WebKit lets a video play without a tap only while its muted *property* is true; set it, and inline playback, as
      // properties and attributes before there is anything to play.
      video.muted = true
      video.defaultMuted = true
      video.playsInline = true
      video.setAttribute('muted', '')
      video.setAttribute('playsinline', '')
      view.sources(sources)
      // The sources are chosen now, by load(); play() after it, so that the load does not abort it.
      video.load()
      update()
    },
    stop() {
      if (!started) return
      started = false
      stopped = false
      shown = false
      pausing = false
      state.userPaused = false
      video.pause()
      view.sources([])
      video.load()
      draw()
    },
    press() {
      if (state.userPaused || stopped) {
        state.userPaused = false
        stopped = false
      } else {
        state.userPaused = true
      }
      draw()
      update()
    },
    seen(onScreen) {
      state.onScreen = onScreen
      update()
    },
    visible(pageVisible) {
      state.pageVisible = pageVisible
      update()
    },
  }
}
