// F-904: when the home page's background loop is fetched and played. Pure, so that it is tested in Node; main.ts reads
// the browser's settings into these shapes.

/** What the page knows about the visitor's settings. */
export interface VideoEnvironment {
  /** matchMedia('(prefers-reduced-motion: reduce)') */
  reducedMotion: boolean
  /** navigator.connection?.saveData === true */
  saveData: boolean
  /** navigator.connection?.effectiveType ?? null */
  effectiveType: string | null
}

const SLOW = new Set(['slow-2g', '2g'])

/** Whether to fetch and play the loop at all: never with reduced motion, Save-Data, or a 'slow-2g' or '2g' connection. */
export function wantsVideo(env: VideoEnvironment): boolean {
  return !env.reducedMotion && !env.saveData && (env.effectiveType === null || !SLOW.has(env.effectiveType))
}

export interface PlayState {
  /** The visitor pressed PAUSE. */
  userPaused: boolean
  /** document.visibilityState === 'visible' */
  pageVisible: boolean
  /** Some part of the video is not covered (the hero's first screen is in view). */
  onScreen: boolean
}

/** Whether the loop should be playing now. */
export function shouldPlay(state: PlayState): boolean {
  return !state.userPaused && state.pageVisible && state.onScreen
}
