// The home page's script (F-904, F-907): the background loop and its button, the way back to the top, and the version stamp.
// Nothing else: no analytics, no storage, no request to anyone but this site. The page is whole without it (index.html holds
// every word and link, and the back-to-top link works as a plain link).
import { createLoop, type LoopSource } from './loop'
import { wantsVideo, type VideoEnvironment } from './video'

declare const __MRR_VERSION__: string

/** The Network Information API, where the browser has it (Chrome on Android and desktop; not Safari or Firefox). */
interface Connection {
  saveData?: boolean
  effectiveType?: string
}

/** The bar's height (landing.css, --bar-h): the hero is wholly covered once the first screen is behind it. */
const BAR_HEIGHT = 72

function main(): void {
  const version = document.querySelector('.version')
  if (version !== null && typeof __MRR_VERSION__ === 'string') version.textContent = `V${__MRR_VERSION__}`
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)')
  backToTop(reducedMotion)

  const video = document.querySelector<HTMLVideoElement>('video.race')
  const button = document.querySelector<HTMLButtonElement>('.video-toggle')
  const firstScreen = document.querySelector('.first-screen')
  if (video === null || button === null || firstScreen === null) return

  const environment = (): VideoEnvironment => {
    const connection = (navigator as Navigator & { connection?: Connection }).connection
    return { reducedMotion: reducedMotion.matches, saveData: connection?.saveData === true, effectiveType: connection?.effectiveType ?? null }
  }

  const loop = createLoop(video, {
    sources(list: readonly LoopSource[]) {
      video.replaceChildren(
        ...list.map(([src, type]) => {
          const source = document.createElement('source')
          source.src = src
          source.type = type
          return source
        }),
      )
    },
    button(shown, icon) {
      button.hidden = !shown
      button.setAttribute('aria-label', icon === 'pause' ? 'Pause video' : 'Play video')
      button.setAttribute('aria-pressed', String(icon === 'play'))
    },
  })
  loop.visible(document.visibilityState === 'visible')

  button.addEventListener('click', () => loop.press())
  document.addEventListener('visibilitychange', () => loop.visible(document.visibilityState === 'visible'))
  new IntersectionObserver(
    (entries) => {
      const entry = entries[entries.length - 1]
      if (entry !== undefined) loop.seen(entry.isIntersecting)
    },
    { rootMargin: `-${BAR_HEIGHT}px 0px 0px 0px` },
  ).observe(firstScreen)
  const start = (): void => {
    if (wantsVideo(environment())) loop.start()
  }
  reducedMotion.addEventListener('change', () => (reducedMotion.matches ? loop.stop() : start()))

  // Nothing of the loop is asked for before the page has loaded: the poster and the words come first.
  if (document.readyState === 'complete') start()
  else window.addEventListener('load', start, { once: true })
}

/**
 * The links to "#top" (the footer's BACK TO TOP, the bar's logo): to the top of the page, smoothly unless the visitor
 * prefers reduced motion, with the focus moved to the hero so that the next Tab is PLAY. Without the script they are plain
 * links to the top of the document, which is what "#top" means when no element is called "top".
 */
function backToTop(reducedMotion: MediaQueryList): void {
  const hero = document.querySelector<HTMLElement>('.hero')
  if (hero === null) return
  for (const link of document.querySelectorAll<HTMLAnchorElement>('a[href="#top"]')) {
    link.addEventListener('click', (event) => {
      event.preventDefault()
      window.scrollTo({ top: 0, behavior: reducedMotion.matches ? 'instant' : 'smooth' })
      hero.focus({ preventScroll: true })
    })
  }
}

main()
